import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { CommandeService } from 'src/app/services/commande.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = [];  // Initialiser comme un tableau vide
  fournisseurId: number = 0;
  selectedMedicaments: { medicamentId: number, quantite: number }[] = [];

  showQuantityDialog: boolean = false;  // Contrôle de l'affichage de la modale
  selectedMedicament: Medicament | null = null;  // Médicament sélectionné pour la commande
  quantity: number = 1;  // Quantité entrée par l'utilisateur

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute,
    private commandeService: CommandeService
  ) {}

  ngOnInit(): void {
    this.fournisseurId = Number(this.route.snapshot.paramMap.get('id'));  // Récupérer l'ID du fournisseur
    if (this.fournisseurId) {
      this.getMedicamentsByFournisseur(this.fournisseurId);
    }
  }

  // Récupérer les médicaments d'un fournisseur spécifique
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(
      data => {
        this.medicaments = data || [];
      },
      error => {
        console.error('Erreur lors de la récupération des médicaments', error);
        this.medicaments = []; 
      }
    );
  }

  // Ouvrir la fenêtre pour entrer la quantité pour un médicament
  openQuantityDialog(medicament: Medicament): void {
    this.selectedMedicament = medicament;  // Sauvegarder le médicament sélectionné
    this.showQuantityDialog = true;  // Afficher la fenêtre de saisie
    this.quantity = 1;  // Réinitialiser la quantité
  }

  // Fermer la fenêtre modale
  closeQuantityDialog(): void {
    this.showQuantityDialog = false;  // Cacher la fenêtre de saisie
  }

  // Ajouter le médicament à la commande après avoir validé la quantité
  addToSelection(): void {
    if (this.selectedMedicament && this.quantity > 0) {
      const existing = this.selectedMedicaments.find(item => item.medicamentId === this.selectedMedicament.idmedicament);
      if (existing) {
        existing.quantite = this.quantity;  // Mettre à jour la quantité
      } else {
        this.selectedMedicaments.push({ medicamentId: this.selectedMedicament.idmedicament, quantite: this.quantity });
      }
      this.closeQuantityDialog();  // Fermer la fenêtre après l'ajout
    }
  }

  // Passer la commande
  passerCommande(): void {
    if (this.selectedMedicaments.length === 0) return;  // Prévenir si aucune sélection
    const commande = {
      fournisseurId: this.fournisseurId,
      status: 'Encours',
      medicaments: this.selectedMedicaments
    };

    this.commandeService.passerCommande(commande).subscribe(
      response => {
        console.log('Commande passée avec succès', response);
        alert('Commande passée avec succès !');
        this.selectedMedicaments = []; // Réinitialiser la sélection après la commande
      },
      error => {
        console.error('Erreur lors de la commande', error);
        alert('Erreur lors de la commande.');
      }
    );
  }
}
<h2>Liste des Médicaments</h2>

<!-- Vérifier si les médicaments existent avant de boucler -->
<ul *ngIf="medicaments && medicaments.length > 0; else noMedicament">
  <li *ngFor="let medicament of medicaments">
    {{ medicament.nom }} - Prix: {{ medicament.prix }}€

    <!-- Bouton 'Commander' qui affiche un champ de saisie pour la quantité -->
    <button (click)="openQuantityDialog(medicament)">Commander</button>
  </li>
</ul>

<!-- Message lorsque aucun médicament n'est trouvé -->
<ng-template #noMedicament>
  <p>Aucun médicament disponible pour ce fournisseur.</p>
</ng-template>

<!-- Le bouton pour passer la commande, désactivé si aucun médicament n'est sélectionné -->
<button (click)="passerCommande()" [disabled]="selectedMedicaments.length === 0">
  Passer la Commande
</button>

<!-- Fenêtre modale pour saisir la quantité -->
<div *ngIf="showQuantityDialog" class="modal">
  <div class="modal-content">
    <span class="close" (click)="closeQuantityDialog()">×</span>
    <h3>Entrez la quantité pour {{ selectedMedicament?.nom }}</h3>
    <input 
      type="number" 
      [(ngModel)]="quantity" 
      min="1" 
      placeholder="Quantité"
      (ngModelChange)="validateQuantity()"
    />
    <button (click)="addToSelection()">Ajouter à la commande</button>
  </div>
</div>
